"""shop_files: generated by Workbench from shop_files.pipeline.yml.

Workbench rewrites this file when you save the pipeline; change the pipeline there.
To run it yourself, set the environment variables Workbench lists in the pipeline's Code tab.
"""
import os

import dlt
from dlt.sources.filesystem import filesystem, read_csv

PROJECT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


BUCKET_URL = os.path.join(PROJECT_DIR, 'seeds')

def source():
    resources = []
    files = filesystem(bucket_url=BUCKET_URL, file_glob='raw_customers.csv')
    resources.append((files | read_csv()).with_name('customers'))
    files = filesystem(bucket_url=BUCKET_URL, file_glob='raw_orders.csv')
    resources.append((files | read_csv()).with_name('orders'))
    return resources


if __name__ == "__main__":
    pipeline = dlt.pipeline(
        pipeline_name='shop_files',
        destination='duckdb',
        dataset_name='raw_files',
        progress="log",
    )
    info = pipeline.run(
        source(),
        write_disposition='replace',
        refresh=os.environ.get("WORKBENCH_REFRESH") or None,
    )
    print(info)
